export interface BOQItem {
  [key: string]: string;
}

export interface BatteryBreakdownItem {
  no: string;
  description: string;
  qty: string;
  unit: string;
  category: string;
}

export interface BOQCategory {
  id: string;
  name: string;
  isSparepart: boolean;
  group: 'Power & Distribution' | 'Power Generation & Fuel' | 'Grounding, Protection & Leak' | 'HVAC & Cooling Systems' | 'Fire Safety & Mechanical' | 'Spareparts & Consumables' | 'General Asset';
  titles: string[];
  headers: string[];
  items: BOQItem[];
  itemCount: number;
  signatures: string[];
  sideTable?: {
    title: string;
    headers: string[];
    rows: BatteryBreakdownItem[];
  } | null;
}

